-- À exécuter dans le SQL Editor de Supabase Dashboard
-- https://supabase.com/dashboard/project/rqijaagnyqjcbelaygzi/sql/new

create table public.blog_articles (
  id           uuid primary key default gen_random_uuid(),
  slug         text unique not null,
  category     text not null default 'ai',
  published_at timestamptz not null default now(),
  read_min     integer not null default 5,
  content      jsonb not null default '{}',
  published    boolean not null default false,
  created_at   timestamptz not null default now()
);

-- content JSONB structure:
-- {
--   "fr": { "title": "...", "excerpt": "...", "tag": "...", "body": "<h2>...</h2><p>...</p>" },
--   "en": { ... },
--   "ar": { ... }
-- }

alter table public.blog_articles enable row level security;

create policy "public read published" on public.blog_articles
  for select using (published = true);

create policy "anon insert" on public.blog_articles
  for insert with check (true);

create policy "anon update" on public.blog_articles
  for update using (true);

-- Seed : 4 articles de démonstration
insert into public.blog_articles (slug, category, read_min, published, content) values
(
  'ia-gestion-emails-entreprise', 'ai', 5, true,
  '{"fr":{"title":"Comment l''IA transforme la gestion des emails en entreprise","excerpt":"Les dirigeants passent en moyenne 2h30 par jour sur leurs emails. Découvrez comment un assistant exécutif IA peut trier, prioriser et rédiger des réponses à votre place.","tag":"IA & Agents","body":"<h2>Un problème universel</h2><p>La surcharge email est l''un des problèmes de productivité les plus répandus en entreprise. Selon McKinsey, les travailleurs du savoir passent 28 % de leur temps à gérer leur boîte de réception.</p><h2>Ce que fait un assistant exécutif IA</h2><p>Un agent IA connecté à votre messagerie peut analyser chaque email entrant, lui attribuer une priorité, suggérer une réponse ou la rédiger entièrement — tout en apprenant vos préférences au fil du temps.</p><h2>Résultats concrets</h2><p>Nos clients rapportent en moyenne <strong>1h45 économisées par jour</strong> après déploiement d''un assistant email IA. Le traitement des emails urgents passe de 4h à moins de 30 minutes.</p><h2>Comment démarrer</h2><p>EasyDigia configure votre assistant en 2 semaines : connexion à votre messagerie, formation sur votre style de communication, règles de priorité personnalisées. Contactez-nous pour une démonstration.</p>"},"en":{"title":"How AI is transforming email management in business","excerpt":"Executives spend an average of 2.5 hours a day on emails. Discover how an executive AI assistant can sort, prioritize and draft replies for you.","tag":"AI & Agents","body":"<h2>A universal problem</h2><p>Email overload is one of the most widespread productivity issues in business. According to McKinsey, knowledge workers spend 28% of their time managing their inbox.</p><h2>What an executive AI assistant does</h2><p>An AI agent connected to your email can analyze each incoming message, assign a priority, suggest a reply or draft it entirely — while learning your preferences over time.</p><h2>Concrete results</h2><p>Our clients report an average of <strong>1h45 saved per day</strong> after deploying an email AI assistant. Processing urgent emails drops from 4 hours to under 30 minutes.</p><h2>How to get started</h2><p>EasyDigia configures your assistant in 2 weeks: connection to your email, training on your communication style, custom priority rules. Contact us for a demo.</p>"},"ar":{"title":"كيف يُحوِّل الذكاء الاصطناعي إدارة البريد الإلكتروني في الشركات","excerpt":"يقضي المدراء في المتوسط ساعتين ونصف يومياً على بريدهم الإلكتروني.","tag":"الذكاء الاصطناعي","body":"<h2>مشكلة عالمية</h2><p>يُعدّ الإرهاق من البريد الإلكتروني من أكثر مشكلات الإنتاجية انتشاراً في بيئة العمل.</p><h2>ما يفعله المساعد الذكي</h2><p>يستطيع وكيل الذكاء الاصطناعي المتصل ببريدك تحليل كل رسالة واردة وتحديد أولويتها واقتراح رد أو صياغته كاملاً.</p><h2>نتائج ملموسة</h2><p>يوفر عملاؤنا <strong>ساعة و45 دقيقة يومياً</strong> بعد نشر مساعد البريد الإلكتروني.</p>"}}'
),
(
  '5-processus-automatiser-pme', 'automation', 7, true,
  '{"fr":{"title":"5 processus à automatiser dès maintenant dans votre PME","excerpt":"Relances clients, reporting hebdomadaire, onboarding collaborateur… Ces 5 tâches peuvent être automatisées cette semaine.","tag":"Automatisation","body":"<h2>Pourquoi automatiser maintenant ?</h2><p>L''automatisation n''est plus réservée aux grands groupes. Les PME qui automatisent leurs processus clés gagnent en moyenne 15h par semaine et réduisent leurs erreurs de 70 %.</p><h2>1. Les relances clients</h2><p>Un workflow automatisé envoie des rappels personnalisés au bon moment, sans intervention humaine. Résultat : taux de recouvrement amélioré de 30 %.</p><h2>2. Le reporting hebdomadaire</h2><p>Collectez vos données depuis plusieurs sources (CRM, comptabilité, marketing) et générez automatiquement un rapport PDF chaque lundi matin.</p><h2>3. L''onboarding des nouveaux collaborateurs</h2><p>Envoi automatique des accès, planning de formation, checklist d''intégration — tout se déclenche dès la signature du contrat.</p><h2>4. La qualification des leads</h2><p>Chaque nouveau contact reçoit une série d''emails personnalisés. Les leads chauds sont transmis automatiquement à votre commercial.</p><h2>5. La facturation et les suivis</h2><p>Générez et envoyez vos factures automatiquement, avec relance si non-paiement. Connectez votre outil de facturation à votre CRM en quelques heures.</p>"},"en":{"title":"5 processes to automate right now in your SME","excerpt":"Client follow-ups, weekly reporting, employee onboarding… These 5 tasks can be automated this week.","tag":"Automation","body":"<h2>Why automate now?</h2><p>Automation is no longer reserved for large corporations. SMEs that automate key processes gain an average of 15 hours per week and reduce errors by 70%.</p><h2>1. Client follow-ups</h2><p>An automated workflow sends personalized reminders at the right time, without human intervention. Result: 30% improvement in collection rate.</p><h2>2. Weekly reporting</h2><p>Collect data from multiple sources and automatically generate a PDF report every Monday morning.</p><h2>3. Employee onboarding</h2><p>Automatic sending of access credentials, training schedule, integration checklist — everything triggers upon contract signing.</p><h2>4. Lead qualification</h2><p>Each new contact receives a series of personalized emails. Hot leads are automatically forwarded to your sales rep.</p><h2>5. Invoicing and follow-ups</h2><p>Generate and send invoices automatically, with reminders for non-payment. Connect your invoicing tool to your CRM in a few hours.</p>"},"ar":{"title":"5 عمليات يجب أتمتتها الآن في شركتك الصغيرة","excerpt":"متابعة العملاء، التقارير الأسبوعية، استقبال الموظفين الجدد… هذه المهام الخمس يمكن أتمتتها هذا الأسبوع.","tag":"الأتمتة","body":"<h2>لماذا الأتمتة الآن؟</h2><p>الأتمتة لم تعد حكراً على الشركات الكبرى. الشركات الصغيرة التي تُؤتمت عملياتها الرئيسية توفر 15 ساعة أسبوعياً وتقلل الأخطاء بنسبة 70%.</p><h2>1. متابعة العملاء</h2><p>سير عمل آلي يرسل تذكيرات مخصصة في الوقت المناسب دون تدخل بشري.</p><h2>2. التقارير الأسبوعية</h2><p>اجمع بياناتك من مصادر متعددة وأنشئ تقرير PDF تلقائياً كل صباح اثنين.</p><h2>3. استقبال الموظفين الجدد</h2><p>إرسال تلقائي لبيانات الوصول وجدول التدريب وقائمة التكامل عند التوقيع على العقد.</p>"}}'
),
(
  'agents-ia-vs-automatisation-classique', 'ai', 6, true,
  '{"fr":{"title":"Agents IA vs automatisation classique : quelle différence ?","excerpt":"Un workflow Zapier et un agent IA ne font pas la même chose. Comprenez les différences fondamentales.","tag":"IA & Agents","body":"<h2>L''automatisation classique : des règles fixes</h2><p>Les outils comme Zapier, Make ou n8n exécutent des séquences d''actions prédéfinies : « si X alors Y ». Ils sont rapides à configurer et parfaits pour les processus répétitifs et prévisibles.</p><h2>Les agents IA : raisonnement et adaptation</h2><p>Un agent IA ne suit pas de règles — il raisonne. Face à une situation inédite, il analyse le contexte, prend une décision et exécute la meilleure action. Il peut gérer l''ambiguïté, comprendre le langage naturel et apprendre de ses erreurs.</p><h2>Quand utiliser quoi ?</h2><p><strong>Automatisation classique</strong> : facturation récurrente, synchronisation de données, notifications automatiques.</p><p><strong>Agent IA</strong> : support client complexe, qualification de leads, analyse de documents, prise de décision contextuelle.</p><h2>La combinaison gagnante</h2><p>Les meilleurs systèmes combinent les deux : des workflows classiques pour la plomberie répétitive, des agents IA pour les tâches qui demandent du jugement. C''est l''approche qu''EasyDigia déploie pour ses clients.</p>"},"en":{"title":"AI agents vs classic automation: what''s the difference?","excerpt":"A Zapier workflow and an AI agent are not the same thing. Understand the fundamental differences.","tag":"AI & Agents","body":"<h2>Classic automation: fixed rules</h2><p>Tools like Zapier, Make or n8n execute predefined action sequences: \"if X then Y\". They are quick to set up and perfect for repetitive, predictable processes.</p><h2>AI agents: reasoning and adaptation</h2><p>An AI agent doesn''t follow rules — it reasons. When faced with a new situation, it analyzes context, makes a decision and executes the best action. It can handle ambiguity, understand natural language and learn from mistakes.</p><h2>When to use which?</h2><p><strong>Classic automation</strong>: recurring billing, data sync, automatic notifications.</p><p><strong>AI agent</strong>: complex customer support, lead qualification, document analysis, contextual decision-making.</p><h2>The winning combination</h2><p>The best systems combine both: classic workflows for repetitive plumbing, AI agents for tasks that require judgment. That''s the approach EasyDigia deploys for its clients.</p>"},"ar":{"title":"وكلاء الذكاء الاصطناعي مقابل الأتمتة الكلاسيكية: ما الفرق؟","excerpt":"سير عمل Zapier ووكيل الذكاء الاصطناعي ليسا الشيء نفسه. افهم الفروق الجوهرية.","tag":"الذكاء الاصطناعي","body":"<h2>الأتمتة الكلاسيكية: قواعد ثابتة</h2><p>أدوات مثل Zapier وMake تنفذ تسلسلات إجراءات محددة مسبقاً. سريعة الإعداد ومثالية للعمليات المتكررة والمتوقعة.</p><h2>وكلاء الذكاء الاصطناعي: التفكير والتكيف</h2><p>وكيل الذكاء الاصطناعي لا يتبع قواعد — بل يستدل. يحلل السياق ويتخذ القرار وينفذ الإجراء الأفضل.</p><h2>متى تستخدم أيهما؟</h2><p><strong>الأتمتة الكلاسيكية</strong>: الفوترة المتكررة، مزامنة البيانات.<br/><strong>وكيل الذكاء الاصطناعي</strong>: دعم العملاء المعقد، تأهيل العملاء المحتملين.</p>"}}'
),
(
  'tableau-de-bord-ia-performances', 'strategy', 8, true,
  '{"fr":{"title":"Pilotez vos performances avec un tableau de bord IA","excerpt":"Un bon tableau de bord ne se contente pas d''afficher des chiffres — il alerte, prédit et recommande.","tag":"Stratégie digitale","body":"<h2>Au-delà des chiffres</h2><p>Un tableau de bord classique affiche ce qui s''est passé. Un tableau de bord IA va plus loin : il détecte les anomalies, prédit les tendances et recommande des actions.</p><h2>Les 4 composantes d''un dashboard intelligent</h2><p><strong>1. Données en temps réel</strong> : connecté à vos sources (CRM, ERP, analytics) avec actualisation automatique.</p><p><strong>2. Alertes intelligentes</strong> : notification immédiate si un indicateur dépasse un seuil critique.</p><p><strong>3. Prédictions</strong> : projection des revenus, des leads ou du churn sur les 30/60/90 prochains jours.</p><p><strong>4. Recommandations</strong> : l''IA suggère les actions prioritaires en fonction des données observées.</p><h2>Exemple concret</h2><p>Un de nos clients dans le retail a réduit son taux de churn de 18 % en 3 mois grâce à un dashboard qui identifiait les clients à risque avant qu''ils ne partent.</p><h2>Comment EasyDigia peut vous aider</h2><p>Nous construisons votre tableau de bord sur-mesure en 3 à 6 semaines, connecté à vos outils existants. Contactez-nous pour un audit de vos données.</p>"},"en":{"title":"Drive your performance with an AI dashboard","excerpt":"A good dashboard doesn''t just display numbers — it alerts, predicts and recommends.","tag":"Digital strategy","body":"<h2>Beyond the numbers</h2><p>A classic dashboard shows what happened. An AI dashboard goes further: it detects anomalies, predicts trends and recommends actions.</p><h2>The 4 components of an intelligent dashboard</h2><p><strong>1. Real-time data</strong>: connected to your sources (CRM, ERP, analytics) with automatic refresh.</p><p><strong>2. Smart alerts</strong>: immediate notification if an indicator crosses a critical threshold.</p><p><strong>3. Predictions</strong>: revenue, lead or churn projections for the next 30/60/90 days.</p><p><strong>4. Recommendations</strong>: AI suggests priority actions based on observed data.</p><h2>Concrete example</h2><p>One of our retail clients reduced their churn rate by 18% in 3 months thanks to a dashboard that identified at-risk customers before they left.</p><h2>How EasyDigia can help</h2><p>We build your custom dashboard in 3 to 6 weeks, connected to your existing tools. Contact us for a data audit.</p>"},"ar":{"title":"قُد أداءك بلوحة معلومات مدعومة بالذكاء الاصطناعي","excerpt":"لوحة المعلومات الجيدة لا تعرض الأرقام فحسب — بل تُنبّه وتتنبأ وتوصي.","tag":"الاستراتيجية الرقمية","body":"<h2>ما وراء الأرقام</h2><p>لوحة المعلومات التقليدية تعرض ما حدث. لوحة الذكاء الاصطناعي تذهب أبعد: تكتشف الشذوذات وتتنبأ بالاتجاهات وتوصي بالإجراءات.</p><h2>المكونات الأربعة للوحة ذكية</h2><p><strong>1. بيانات في الوقت الفعلي</strong>: متصلة بمصادرك مع تحديث تلقائي.</p><p><strong>2. تنبيهات ذكية</strong>: إشعار فوري إذا تجاوز مؤشر حداً حرجاً.</p><p><strong>3. تنبؤات</strong>: توقعات الإيرادات والعملاء للـ 30/60/90 يوماً القادمة.</p>"}}'
);
